-- Seed for the demo SQLite database (generated by scripts/make-sample-db.mjs).
-- Fictional data only. Schema: customers <- orders <- order_items -> products, plus a view.
CREATE TABLE customers (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT UNIQUE,
  created_at TEXT NOT NULL
);
CREATE TABLE products (
  sku TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  price REAL NOT NULL
);
CREATE TABLE orders (
  id INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL REFERENCES customers(id),
  status TEXT NOT NULL,
  placed_at TEXT NOT NULL
);
CREATE TABLE order_items (
  order_id INTEGER NOT NULL REFERENCES orders(id),
  line_no INTEGER NOT NULL,
  sku TEXT NOT NULL REFERENCES products(sku),
  qty INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY (order_id, line_no)
);
CREATE INDEX idx_orders_customer ON orders(customer_id);
CREATE VIEW order_totals AS
  SELECT o.id AS order_id, o.status AS status, sum(i.qty * p.price) AS total
  FROM orders o
  JOIN order_items i ON i.order_id = o.id
  JOIN products p ON p.sku = i.sku
  GROUP BY o.id;

